import{_ as e,o as t,c as o,a3 as i}from"./chunks/framework.DdpBa4_E.js";const p=JSON.parse('{"title":"前言与作者简介","description":"","frontmatter":{},"headers":[],"relativePath":"books/jingying-weilai/03-前言与作者简介.md","filePath":"books/jingying-weilai/03-前言与作者简介.md","lastUpdated":1795076791000}'),r={name:"books/jingying-weilai/03-前言与作者简介.md"};function n(_,a,l,s,d,h){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="前言与作者简介" tabindex="-1">前言与作者简介 <a class="header-anchor" href="#前言与作者简介" aria-label="Permalink to &quot;前言与作者简介&quot;">​</a></h1><h2 id="《经营未来》作者简介" tabindex="-1">《经营未来》作者简介 <a class="header-anchor" href="#《经营未来》作者简介" aria-label="Permalink to &quot;《经营未来》作者简介&quot;">​</a></h2><p>李明博，1941年出生于日本大阪，1960年毕业于浦项同志商业高中（夜间部），1965年毕业于高丽大学经营学系，同年进入现代建设公司，1977年-1988年担任现代建设公司代表理事、社长，1982年-1992年担任韩国商工会议所副会长，1988年-1992年担任现代建设公司代表理事、会长，1992年-1995年第14届国会议员，1996年-1998年第15届国会议员，1999年-2002年担任亚太环境NGO韩国本部总裁，2002年-2006年第32届首尔特别市市长（民选3期），2007年当选为韩国第17属总统。</p><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>自小就有的梦想，一生都在我心中澎湃： 我喜欢冒险与挑战所带来的热情与振奋，我一直梦想社会安定、经济安乐以及透过文化而获得快乐的“幸福世界”。 我要成为“自己的主人”、“良心的主人”和“事业的主人”。 从一个清理垃圾卖苦力的工读学生，到敢于迎接挑战的学生会主席，到军事政权的反抗者，到打工者，到职业经理人，到首尔市长,到当选总统，是贫困教会了我善于学习、教会了我冷静地思考人生和社会的意义；迫使我执意进取，直面挑战，勇于变革；更让我懂得了把握未来、经营未来的重要。 人必有所守护，方能有所坚持。我贯彻一生要为国民幸福坚持奋力拼搏；我愿意在任何危机、挑战面前，毅然迎上前去；我坚持再苦、再难也要堂堂正正地做人。这是在经历了艰难的成长、求学、事业开拓之后，珍藏于内心的一个坚定信念。 我感谢我的国民对我的信任和支持，也感谢我的读者们愿意跟我分享我的快乐、信念和感受。你们是真正值得尊敬的。 很高兴此书由中国最权威的出版社 ——人民出版社出版，也非常感谢参与此书编辑工作的所有中韩两国专家。愿此书能为中韩两国的友谊做出贡献，也希望能给中国广大有抱负的年轻人一个梦想。 再次对中韩两国国民和读者表示敬意！</p><h2 id="第一部分" tabindex="-1">第一部分 <a class="header-anchor" href="#第一部分" aria-label="Permalink to &quot;第一部分&quot;">​</a></h2><p>我在风中行走。</p><p>回望这六十多年，我从未走过舒适安逸的路。首先是因为生活的时代环境，其次是个人性格所致。我不喜欢走安逸的捷径，我喜欢冒险与挑战所带来的热情与振奋。另外，则是因为我一直无法抛弃“幸福世界”的梦想。我相信，所谓幸福的世界，就是社会安定、经济安乐以及透过文化而获得快乐。我之所以有这样的性格与理想，或许都开端于早年如影随形的贫穷……</p>',8)])])}const m=e(r,[["render",n]]);export{p as __pageData,m as default};
